/* Check functions with known satisfying inputs, for function-level symbolic solving.
 * Usage: lines of "name x y" on stdin; prints each check's result (0 or 1). */
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#if defined(__clang__)
#define CHECK __attribute__((noinline, used))
#else
#define CHECK __attribute__((noipa, used))
#endif

